 private function restorePreflight($m,$scope){
  if(!in_array($scope,['data','files','both'],true))return;
  foreach($m['files'] as $f){
   if($f['mount']==='site'&&$f['path']==='.env')continue;
   if($scope==='data'&&($f['mount']!=='site'||strpos($f['path'],'public/uploads/')!==0))continue;
